import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import shippingAPI from "../../services/shippingService";

export default function CheckServiceability() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    origin: "",
    destination: "",
    payment_type: "prepaid",
    order_amount: "",
    weight: ""
  });

  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleInputChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    setResults(null);

    // Validate required fields
    if (!formData.origin || !formData.destination || !formData.order_amount) {
      setError("Please fill all required fields");
      setLoading(false);
      return;
    }

    try {
      const serviceabilityData = {
        origin: formData.origin.trim(),
        destination: formData.destination.trim(),
        payment_type: formData.payment_type,
        order_amount: parseFloat(formData.order_amount),
        weight: formData.weight ? parseFloat(formData.weight) : 500 // Default 500g
      };

      const response = await shippingAPI.checkServiceability(serviceabilityData);

      if (response?.data?.status) {
        setResults(response.data.data || []);
      } else {
        setError(response?.data?.message || "No serviceability data found");
      }
    } catch (error) {
      console.error("Serviceability check error:", error);
      setError(error.response?.data?.message || "Error checking serviceability");
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return `₹${amount?.toFixed(2) || '0.00'}`;
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString();
  };

  return (
    <div className="check-serviceability">
      <div className="check-serviceability__header">
        <h3 className="page_heading">Check Serviceability</h3>
        <button
          className="btn btn-secondary"
          onClick={() => navigate("/shipping")}
        >
          Back to Dashboard
        </button>
      </div>

      <div className="check-serviceability__content">
        {/* Form Section */}
        <div className="serviceability-form">
          <form onSubmit={handleSubmit}>
            <div className="form-section">
              <h4>Serviceability Details</h4>
              <div className="form-grid">
                <div className="form-group">
                  <label>Origin Pincode *</label>
                  <input
                    type="text"
                    value={formData.origin}
                    onChange={(e) => handleInputChange("origin", e.target.value)}
                    placeholder="Enter origin pincode"
                    required
                    maxLength={6}
                  />
                </div>

                <div className="form-group">
                  <label>Destination Pincode *</label>
                  <input
                    type="text"
                    value={formData.destination}
                    onChange={(e) => handleInputChange("destination", e.target.value)}
                    placeholder="Enter destination pincode"
                    required
                    maxLength={6}
                  />
                </div>

                <div className="form-group">
                  <label>Payment Type *</label>
                  <select
                    value={formData.payment_type}
                    onChange={(e) => handleInputChange("payment_type", e.target.value)}
                    required
                  >
                    <option value="prepaid">Prepaid</option>
                    <option value="cod">Cash on Delivery (COD)</option>
                  </select>
                </div>

                <div className="form-group">
                  <label>Order Amount (₹) *</label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.order_amount}
                    onChange={(e) => handleInputChange("order_amount", e.target.value)}
                    placeholder="Enter order amount"
                    required
                    min="0"
                  />
                </div>

                <div className="form-group">
                  <label>Weight (grams)</label>
                  <input
                    type="number"
                    value={formData.weight}
                    onChange={(e) => handleInputChange("weight", e.target.value)}
                    placeholder="Default: 500g"
                    min="1"
                  />
                  <small className="form-help">Leave empty for default (500g)</small>
                </div>
              </div>

              <div className="form-actions">
                <button
                  type="submit"
                  className="btn btn-primary"
                  disabled={loading}
                >
                  {loading ? "Checking..." : "Check Serviceability"}
                </button>
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => {
                    setFormData({
                      origin: "",
                      destination: "",
                      payment_type: "prepaid",
                      order_amount: "",
                      weight: ""
                    });
                    setResults(null);
                    setError("");
                  }}
                >
                  Reset
                </button>
              </div>

              {error && <div className="error-message">{error}</div>}
            </div>
          </form>
        </div>

        {/* Results Section */}
        {results && results.length > 0 && (
          <div className="serviceability-results">
            <h4>Available Shipping Options</h4>
            <div className="results-grid">
              {results.map((option, index) => (
                <div key={index} className="serviceability-card">
                  <div className="card-header">
                    <h5>{option.courier_name || 'Xpressbees'}</h5>
                    <div className="total-price">
                      {formatCurrency(option.total_amount)}
                    </div>
                  </div>

                  <div className="card-body">
                    <div className="price-breakdown">
                      <div className="price-item">
                        <span className="label">Base Rate:</span>
                        <span className="value">{formatCurrency(option.base_rate)}</span>
                      </div>
                      {option.fuel_surcharge > 0 && (
                        <div className="price-item">
                          <span className="label">Fuel Surcharge:</span>
                          <span className="value">{formatCurrency(option.fuel_surcharge)}</span>
                        </div>
                      )}
                      {formData.payment_type === 'cod' && option.cod_charges > 0 && (
                        <div className="price-item">
                          <span className="label">COD Charges:</span>
                          <span className="value">{formatCurrency(option.cod_charges)}</span>
                        </div>
                      )}
                      <div className="price-item total">
                        <span className="label">Total Amount:</span>
                        <span className="value">{formatCurrency(option.total_amount)}</span>
                      </div>
                    </div>

                    {option.estimated_delivery && (
                      <div className="delivery-info">
                        <span className="label">Estimated Delivery:</span>
                        <span className="value">{formatDate(option.estimated_delivery)}</span>
                      </div>
                    )}

                    {option.serviceable && (
                      <div className="serviceable-badge">
                        ✓ Serviceable
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {results && results.length === 0 && (
          <div className="no-results">
            <p>No shipping options available for the given pincodes.</p>
          </div>
        )}
      </div>
    </div>
  );
}